contract InvMutTest {
    C c;
    constructor() { c = new C(address(this), address(this)); }
    function __ESBMC_reverted() internal returns (bool) {}
    function __ESBMC_assume(bool) internal pure {}

    // single public test entry
    function run(address neuronAddress, uint256 tokenId, uint256 quantity) public payable {
        require(quantity > 0);

        // set up: instantiate the Neuron contract in C (this contract is the owner of C as per harness rules)
        c.instantiateNeuronContract(neuronAddress); if (__ESBMC_reverted()) return;

        // read before-values via public view functions
        uint256 beforeBalance = c.balanceOf(address(this), tokenId); if (__ESBMC_reverted()) return;

        // attempt the purchase/mint; top-level state-changing call with try/catch
        bool reverted;
        c.mint(tokenId, quantity); bool __rev0 = __ESBMC_reverted(); if (__rev0) {
            reverted = true;
        } else {
            reverted = false;
        }

        // read after-value
        uint256 afterBalance = c.balanceOf(address(this), tokenId); if (__ESBMC_reverted()) return;

        // general invariant: if mint succeeded (did not revert) then caller's ERC1155 balance increased by exactly quantity
        assert(reverted || afterBalance == beforeBalance + quantity);
    }

    receive() external payable {}
}

