pragma solidity ^0.8.0;

import {Test} from "forge-std/Test.sol";
import {GameItems} from "../src/GameItems.sol";

contract InvMutTest is Test {
    uint256 internal constant VALUE_CAP = 1000000000000000000000000000000;
    GameItems c;

    function setUp() public {
        c = new GameItems(address(this), address(this));
    }

    function _run(address neuronAddress, uint256 tokenId, uint256 quantity) internal {
        vm.assume(quantity > 0);
        try c.instantiateNeuronContract(neuronAddress) {} catch { return; }
        uint256 beforeBalance;
        try c.balanceOf(address(this), tokenId) returns (uint256 __r) { beforeBalance = __r; } catch { return; }
        bool reverted;
        try c.mint(tokenId, quantity) {
            reverted = false;
        } catch {
            reverted = true;
        }
        uint256 afterBalance;
        try c.balanceOf(address(this), tokenId) returns (uint256 __r) { afterBalance = __r; } catch { return; }
        assertTrue(reverted || afterBalance == beforeBalance + quantity);
    }

    function testFuzz_run(address neuronAddress, uint256 tokenId, uint256 quantity) public {
        vm.assume(neuronAddress.code.length == 0 && uint160(neuronAddress) > 0xffff && neuronAddress != address(this) && neuronAddress != address(c) && neuronAddress != 0x7109709ECfa91a80626fF3989D68f67F5b1DD12D && neuronAddress != 0x000000000000000000636F6e736F6c652e6c6f67 && neuronAddress != 0x4e59b44847b379578588920cA78FbF26c0B4956C && neuronAddress != 0x1804c8AB1F12E6bbf3894d4083f33e07309d1f38);
        _run(neuronAddress, tokenId, quantity);
    }

    receive() external payable {}
}
